require "rails_helper"

RSpec.describe Timekeeping::SnapshotValues do
  # "These checks validate field names and entry identifiers, but not source values."
  it "names source as invalid for agent or a non-string value and accepts every allowed source" do
    snapshot = {
      "id" => 9, "project_id" => 5, "user_id" => 6, "agent_id" => nil, "work_date" => "2026-03-02",
      "duration" => BigDecimal("30.5"), "note" => "", "bill_status" => "unbilled", "review_status" => "not_required",
      "locked" => false, "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
      "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {}, "discarded_at" => nil,
      "created_at" => "2026-03-02T09:00:00Z", "updated_at" => "2026-03-02T09:00:00Z", "company_id" => 41
    }

    ["agent", ["manual"], 1, nil, { "name" => "manual" }].each do |source|
      expect(described_class.invalid_fields(snapshot.merge("source" => source))).to eq(["source"])
    end
    %w[manual cli mcp automation import].each do |source|
      expect(described_class.invalid_fields(snapshot.merge("source" => source))).to eq([])
    end
  end
end

