require "rails_helper"

RSpec.describe Timekeeping::SnapshotValues do
  def snapshot_values_base_snapshot
    {
      "id" => 11, "company_id" => 1, "project_id" => 10, "user_id" => 20, "agent_id" => nil,
      "work_date" => Date.new(2026, 3, 2), "duration" => 30.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => Time.utc(2026, 3, 2, 9), "updated_at" => Time.utc(2026, 3, 2, 9)
    }
  end

  def snapshot_values_nested(levels)
    levels.times.reduce("leaf") { |value, _| { "child" => value } }
  end

  # "producers must reject values that stop delivery for everyone"
  it "names each field whose value the projection or the relay would refuse, one at a time" do
    expect(described_class.invalid_fields(snapshot_values_base_snapshot)).to eq([])

    refused = {
      "bill_status" => "paid", "review_status" => 1, "locked" => "true", "duration" => -1,
      "work_date" => "2026-02-30", "created_at" => "yesterday", "updated_at" => nil, "discarded_at" => "x",
      "project_id" => 0, "user_id" => "5", "agent_id" => -3, "note" => 4, "external_run_id" => 7,
      "source_metadata" => [], "proof_metadata" => snapshot_values_nested(97), "company_id" => -1, "id" => "11"
    }
    refused.each do |field, value|
      expect(described_class.invalid_fields(snapshot_values_base_snapshot.merge(field => value))).to eq([field])
    end

    deepest = snapshot_values_base_snapshot.merge("source_metadata" => snapshot_values_nested(96))
    expect(described_class.invalid_fields(deepest)).to eq([])
  end
end

